use vstd::prelude::*;
use vstd::vec::Vec;

verus! {

    /// Given two non-empty 32-bit floating‐point arrays `x` and `y`,
    /// construct their Cartesian mesh grid:
    /// returns `(X, Y)` where
    ///   - X is a matrix of size y.len() × x.len() with X[i][j] = x[j]
    ///   - Y is a matrix of size y.len() × x.len() with Y[i][j] = y[i]
    pub fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>)
        requires
            x.len() > 0,
            y.len() > 0,
        ensures
            // let (X_out, Y_out) be the returned pair
            let (ref X_out, ref Y_out) = result;
            // Dimensions match
            X_out.len() == y.len() &&
            Y_out.len() == y.len() &&
            // For each row i
            forall |i: usize|
                i < y.len() ==>
                  // Each row has x.len() columns
                  X_out[i].len() == x.len() &&
                  Y_out[i].len() == x.len() &&
                  // And elements are placed correctly
                  forall |j: usize|
                    j < x.len() ==>
                      X_out[i][j] == x[j] &&
                      Y_out[i][j] == y[i],
    {
        // We'll build X_out and Y_out row by row
        let mut X_out: Vec<Vec<f32>> = Vec::new();
        let mut Y_out: Vec<Vec<f32>> = Vec::new();

        let mut i = 0;
        // Iterate over each entry of `y` to form the rows
        while i < y.len() {
            decreases y.len() - i;

            // Build the i-th row of the grid
            let mut row_x: Vec<f32> = Vec::new();
            let mut row_y: Vec<f32> = Vec::new();
            let mut j = 0;
            while j < x.len() {
                decreases x.len() - j;
                
                // For the X matrix, copy x[j]
                row_x.push(x[j]);
                // For the Y matrix, copy y[i]
                row_y.push(y[i]);

                j += 1;
            }
            // After the inner loop, each row has length x.len()
            assert(row_x.len() == x.len());
            assert(row_y.len() == x.len());

            // Append the completed rows
            X_out.push(row_x);
            Y_out.push(row_y);

            i += 1;
        }

        (X_out, Y_out)
    }
}